contracts/registry/ComplianceRegistry.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title ComplianceRegistry
 * @notice On-chain identity / KYC attestation registry for DEXless RWA markets.
 *
 * Off-chain KYC is performed by a licensed provider. The provider (or an
 * operator acting on its behalf) writes a *hash* of the verification record
 * on-chain — never the PII itself. Every RWA token transfer and every market
 * proposal consults this registry.
 *
 * This contract is the "compliance / KYC / identity module" required by the
 * BNB Chain RWA Infra track, and it doubles as the canonical source of the
 * project's verifiable real-user count: `verifiedCount()` can only be
 * incremented by a real attestation from an authorised attester.
 */
contract ComplianceRegistry is AccessControl {
    bytes32 public constant ATTESTER_ROLE = keccak256("ATTESTER_ROLE");

    /// @notice Investor classification, drives which assets an account may hold.
    enum Tier {
        NONE, // 0 - not verified
        RETAIL, // 1 - basic KYC
        ACCREDITED, // 2 - accredited / professional investor
        INSTITUTIONAL // 3 - institutional entity
    }

    struct Attestation {
        bytes32 recordHash; // keccak256 of the off-chain KYC record (PII stays off-chain)
        string evidenceURI; // IPFS CID of the encrypted evidence bundle
        uint16 jurisdiction; // ISO-3166-1 numeric country code
        Tier tier;
        uint64 issuedAt;
        uint64 expiresAt;
        address attester;
        bool revoked;
    }

    mapping(address account => Attestation) private _attestations;

    /// @notice Jurisdictions that may not hold any DEXless RWA token.
    mapping(uint16 jurisdiction => bool) public jurisdictionBlocked;

    /// @notice Number of accounts that have ever been successfully attested.
    uint256 public totalAttested;
    /// @notice Number of accounts currently holding a live (non-revoked, non-expired) attestation.
    uint256 public activeAttested;

    event Attested(
        address indexed account,
        address indexed attester,
        Tier tier,
        uint16 jurisdiction,
        uint64 expiresAt,
        bytes32 recordHash
    );
    event AttestationRevoked(address indexed account, address indexed attester, string reason);
    event JurisdictionBlocked(uint16 indexed jurisdiction, bool blocked);

    error AlreadyActive(address account);
    error NotAttested(address account);
    error BlockedJurisdiction(uint16 jurisdiction);
    error InvalidExpiry();
    error InvalidTier();

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ATTESTER_ROLE, admin);
    }

    // ---------------------------------------------------------------------
    // Attestation lifecycle
    // ---------------------------------------------------------------------

    /**
     * @notice Record a KYC attestation for `account`.
     * @param account     Wallet being verified.
     * @param recordHash  keccak256 of the off-chain KYC record.
     * @param evidenceURI IPFS URI of the encrypted evidence bundle.
     * @param jurisdiction ISO-3166-1 numeric country code of the holder.
     * @param tier        Investor classification.
     * @param expiresAt   Unix timestamp after which the attestation lapses.
     */
    function attest(
        address account,
        bytes32 recordHash,
        string calldata evidenceURI,
        uint16 jurisdiction,
        Tier tier,
        uint64 expiresAt
    ) external onlyRole(ATTESTER_ROLE) {
        if (tier == Tier.NONE) revert InvalidTier();
        if (expiresAt <= block.timestamp) revert InvalidExpiry();
        if (jurisdictionBlocked[jurisdiction]) revert BlockedJurisdiction(jurisdiction);

        bool wasActive = isVerified(account);
        bool everAttested = _attestations[account].issuedAt != 0;

        _attestations[account] = Attestation({
            recordHash: recordHash,
            evidenceURI: evidenceURI,
            jurisdiction: jurisdiction,
            tier: tier,
            issuedAt: uint64(block.timestamp),
            expiresAt: expiresAt,
            attester: msg.sender,
            revoked: false
        });

        if (!wasActive) activeAttested += 1;
        // `totalAttested` counts unique wallets ever verified — the figure we
        // report as "verifiable real users". Re-attesting never double-counts.
        if (!everAttested) totalAttested += 1;

        emit Attested(account, msg.sender, tier, jurisdiction, expiresAt, recordHash);
    }

    /// @notice Revoke an existing attestation (e.g. sanctions hit, expired documents).
    function revoke(address account, string calldata reason) external onlyRole(ATTESTER_ROLE) {
        Attestation storage a = _attestations[account];
        if (a.issuedAt == 0) revert NotAttested(account);

        bool wasActive = isVerified(account);
        a.revoked = true;
        if (wasActive && activeAttested > 0) activeAttested -= 1;

        emit AttestationRevoked(account, msg.sender, reason);
    }

    /// @notice Block or unblock an entire jurisdiction.
    function setJurisdictionBlocked(uint16 jurisdiction, bool blocked) external onlyRole(DEFAULT_ADMIN_ROLE) {
        jurisdictionBlocked[jurisdiction] = blocked;
        emit JurisdictionBlocked(jurisdiction, blocked);
    }

    // ---------------------------------------------------------------------
    // Views — consumed by RWAToken and MarketFactory
    // ---------------------------------------------------------------------

    /// @notice True when `account` holds a live attestation from a permitted jurisdiction.
    function isVerified(address account) public view returns (bool) {
        Attestation storage a = _attestations[account];
        return a.issuedAt != 0 && !a.revoked && a.expiresAt > block.timestamp
            && !jurisdictionBlocked[a.jurisdiction];
    }

    /// @notice True when `account` is verified at or above `minTier`.
    function isVerifiedAtLeast(address account, Tier minTier) external view returns (bool) {
        return isVerified(account) && _attestations[account].tier >= minTier;
    }

    function attestationOf(address account) external view returns (Attestation memory) {
        return _attestations[account];
    }

    function tierOf(address account) external view returns (Tier) {
        return isVerified(account) ? _attestations[account].tier : Tier.NONE;
    }
}

contracts/registry/RWAAssetRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title RWAAssetRegistry
 * @notice Canonical on-chain record of every real-world asset admitted to DEXless.
 *
 * Three things live here, and nothing else:
 *   1. WHAT the asset is         — class, issuer, jurisdiction, legal doc hash
 *   2. WHO custodies it          — custodian address + periodic reserve attestations
 *   3. WHETHER it may be used    — lifecycle status gating mint and market creation
 *
 * The custody attestation is the backbone of the 1:1 mapping guarantee:
 * `RWAToken` refuses to mint beyond the most recently attested off-chain unit
 * count, so on-chain supply can never exceed custodied reserves.
 *
 * Legal documents (prospectus, custody agreement, audit report) are pinned to
 * IPFS; only the CID and a keccak256 digest are stored on-chain, so any party
 * can prove the document they hold is the one that was registered.
 */
contract RWAAssetRegistry is AccessControl {
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");

    enum AssetClass {
        UNSPECIFIED,
        FUND_SHARE, // e.g. money-market or mutual fund unit (NAV-priced)
        PRECIOUS_METAL, // e.g. allocated gold in a vault
        RECEIVABLE, // e.g. invoice / trade receivable
        EQUITY,
        BOND,
        COMMODITY,
        REAL_ESTATE,
        OTHER
    }

    enum Status {
        NONE,
        PENDING, // registered, awaiting first custody attestation
        ACTIVE, // tradable + mintable
        SUSPENDED, // temporarily halted (stale attestation, price anomaly, legal event)
        RETIRED // permanently wound down
    }

    struct Asset {
        AssetClass class;
        Status status;
        uint16 jurisdiction; // ISO-3166-1 numeric
        uint8 decimals; // decimals of the off-chain unit count
        string symbol;
        string name;
        address issuer;
        address custodian;
        string legalDocURI; // ipfs://... prospectus / custody agreement
        bytes32 legalDocHash; // keccak256 of that document
        uint64 registeredAt;
    }

    /// @notice Calldata bundle for {registerAsset}, kept as a struct so the
    ///         function stays within the EVM stack limit.
    struct AssetInput {
        AssetClass class;
        string symbol;
        string name;
        address issuer;
        address custodian;
        uint16 jurisdiction;
        uint8 decimals;
        string legalDocURI;
        bytes32 legalDocHash;
    }

    /// @notice Latest reserve attestation signed off by the custodian.
    struct CustodyAttestation {
        // Off-chain units held in custody, ALWAYS expressed in 18-decimal fixed
        // point regardless of Asset.decimals, so that RWAToken (18 decimals) can
        // compare its supply against this figure directly.
        uint256 units;
        bytes32 proofHash; // keccak256 of the custodian's signed statement
        string proofURI; // ipfs://... of that statement
        uint64 attestedAt;
        address attestedBy;
    }

    mapping(bytes32 assetId => Asset) private _assets;
    mapping(bytes32 assetId => CustodyAttestation) private _custody;
    bytes32[] private _assetIds;

    /// @notice Max age of a custody attestation before the asset is considered unbacked.
    uint64 public custodyStaleAfter = 35 days;

    event AssetRegistered(
        bytes32 indexed assetId,
        AssetClass indexed class,
        address indexed issuer,
        address custodian,
        string symbol,
        uint16 jurisdiction,
        bytes32 legalDocHash
    );
    event CustodyAttested(
        bytes32 indexed assetId,
        address indexed custodian,
        uint256 units,
        bytes32 proofHash,
        uint64 attestedAt
    );
    event AssetStatusChanged(bytes32 indexed assetId, Status indexed from, Status indexed to, string reason);
    event CustodyStaleAfterUpdated(uint64 previous, uint64 current);

    error AssetExists(bytes32 assetId);
    error UnknownAsset(bytes32 assetId);
    error NotCustodian(bytes32 assetId, address caller);
    error InvalidTransition(Status from, Status to);
    error ZeroAddress();

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REGISTRAR_ROLE, admin);
    }

    // ---------------------------------------------------------------------
    // Registration
    // ---------------------------------------------------------------------

    /**
     * @notice Admit a real-world asset to the registry. Starts in PENDING and
     *         only becomes ACTIVE once the custodian has attested reserves.
     * @param assetId Deterministic id, conventionally keccak256(abi.encodePacked(symbol, issuer)).
     */
    function registerAsset(bytes32 assetId, AssetInput calldata input) external onlyRole(REGISTRAR_ROLE) {
        if (_assets[assetId].status != Status.NONE) revert AssetExists(assetId);
        if (input.issuer == address(0) || input.custodian == address(0)) revert ZeroAddress();

        _assets[assetId] = Asset({
            class: input.class,
            status: Status.PENDING,
            jurisdiction: input.jurisdiction,
            decimals: input.decimals,
            symbol: input.symbol,
            name: input.name,
            issuer: input.issuer,
            custodian: input.custodian,
            legalDocURI: input.legalDocURI,
            legalDocHash: input.legalDocHash,
            registeredAt: uint64(block.timestamp)
        });
        _assetIds.push(assetId);

        emit AssetRegistered(
            assetId, input.class, input.issuer, input.custodian, input.symbol, input.jurisdiction, input.legalDocHash
        );
    }

    // ---------------------------------------------------------------------
    // Custody attestation — the 1:1 backing proof
    // ---------------------------------------------------------------------

    /**
     * @notice Custodian publishes the current off-chain reserve balance.
     * @dev First successful attestation promotes a PENDING asset to ACTIVE.
     *      This is the call the custodian (or JEPUN's NAV pipeline) makes on a
     *      recurring schedule; every invocation is a real on-chain business event.
     */
    function attestCustody(
        bytes32 assetId,
        uint256 units,
        bytes32 proofHash,
        string calldata proofURI
    ) external {
        Asset storage a = _assets[assetId];
        if (a.status == Status.NONE) revert UnknownAsset(assetId);
        if (msg.sender != a.custodian && !hasRole(REGISTRAR_ROLE, msg.sender)) {
            revert NotCustodian(assetId, msg.sender);
        }

        _custody[assetId] = CustodyAttestation({
            units: units,
            proofHash: proofHash,
            proofURI: proofURI,
            attestedAt: uint64(block.timestamp),
            attestedBy: msg.sender
        });

        emit CustodyAttested(assetId, msg.sender, units, proofHash, uint64(block.timestamp));

        if (a.status == Status.PENDING && units > 0) {
            a.status = Status.ACTIVE;
            emit AssetStatusChanged(assetId, Status.PENDING, Status.ACTIVE, "first custody attestation");
        }
    }

    /// @notice Admin lifecycle control (suspend on legal event, retire on wind-down).
    function setStatus(bytes32 assetId, Status to, string calldata reason) external onlyRole(REGISTRAR_ROLE) {
        Asset storage a = _assets[assetId];
        if (a.status == Status.NONE) revert UnknownAsset(assetId);
        if (to == Status.NONE || to == a.status) revert InvalidTransition(a.status, to);
        if (a.status == Status.RETIRED) revert InvalidTransition(a.status, to);

        Status from = a.status;
        a.status = to;
        emit AssetStatusChanged(assetId, from, to, reason);
    }

    function setCustodyStaleAfter(uint64 newWindow) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit CustodyStaleAfterUpdated(custodyStaleAfter, newWindow);
        custodyStaleAfter = newWindow;
    }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------

    /// @notice True when the asset is ACTIVE *and* its custody attestation is fresh.
    function isMintable(bytes32 assetId) external view returns (bool) {
        Asset storage a = _assets[assetId];
        CustodyAttestation storage c = _custody[assetId];
        return a.status == Status.ACTIVE && c.attestedAt != 0
            && block.timestamp - c.attestedAt <= custodyStaleAfter;
    }

    /// @notice Upper bound on token supply implied by the latest reserve attestation.
    function attestedUnits(bytes32 assetId) external view returns (uint256) {
        return _custody[assetId].units;
    }

    function getAsset(bytes32 assetId) external view returns (Asset memory) {
        if (_assets[assetId].status == Status.NONE) revert UnknownAsset(assetId);
        return _assets[assetId];
    }

    function getCustody(bytes32 assetId) external view returns (CustodyAttestation memory) {
        return _custody[assetId];
    }

    function statusOf(bytes32 assetId) external view returns (Status) {
        return _assets[assetId].status;
    }

    function assetCount() external view returns (uint256) {
        return _assetIds.length;
    }

    function assetIdAt(uint256 index) external view returns (bytes32) {
        return _assetIds[index];
    }
}

contracts/token/FeeDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {MerkleProof} from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import {BitMaps} from "@openzeppelin/contracts/utils/structs/BitMaps.sol";

/**
 * @title FeeDistributor
 * @notice Distributes RWA yield and market fees to entitled holders in rounds.
 *
 * Each round pins an IPFS snapshot of the full entitlement table together with
 * its Merkle root, so any holder can independently recompute the root from the
 * published snapshot and prove the operator did not tamper with allocations.
 * Holders then pull their own share — one on-chain claim per wallet, which is
 * exactly the kind of genuine multi-wallet business activity the market should
 * exhibit.
 *
 * Unclaimed funds can be swept back to the treasury only after the round's
 * claim window has closed.
 */
contract FeeDistributor is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using BitMaps for BitMaps.BitMap;

    bytes32 public constant DISTRIBUTOR_ROLE = keccak256("DISTRIBUTOR_ROLE");

    struct Round {
        bytes32 merkleRoot;
        address token; // asset paid out (e.g. USDT on BNB Chain)
        uint256 totalAmount;
        uint256 claimedAmount;
        uint64 snapshotBlock; // block at which holder balances were snapshotted
        uint64 opensAt;
        uint64 closesAt;
        bool swept;
        string snapshotURI; // ipfs://... full entitlement table
    }

    Round[] private _rounds;
    mapping(uint256 roundId => BitMaps.BitMap) private _claimed;

    address public treasury;

    /// @notice Lifetime number of individual holder claims — a real-user activity metric.
    uint256 public totalClaims;

    event RoundOpened(
        uint256 indexed roundId,
        address indexed token,
        uint256 totalAmount,
        bytes32 merkleRoot,
        uint64 snapshotBlock,
        uint64 opensAt,
        uint64 closesAt,
        string snapshotURI
    );
    event Claimed(uint256 indexed roundId, uint256 indexed index, address indexed account, uint256 amount);
    event RoundSwept(uint256 indexed roundId, address indexed to, uint256 amount);
    event TreasuryUpdated(address indexed previous, address indexed current);

    error UnknownRound(uint256 roundId);
    error RoundNotOpen(uint256 roundId);
    error RoundClosed(uint256 roundId);
    error RoundStillOpen(uint256 roundId);
    error AlreadyClaimed(uint256 roundId, uint256 index);
    error InvalidProof();
    error AlreadySwept(uint256 roundId);
    error InvalidWindow();
    error ZeroAddress();
    error ZeroAmount();

    constructor(address admin, address treasury_) {
        if (treasury_ == address(0)) revert ZeroAddress();
        treasury = treasury_;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(DISTRIBUTOR_ROLE, admin);
    }

    // ---------------------------------------------------------------------
    // Distribution
    // ---------------------------------------------------------------------

    /**
     * @notice Fund and open a distribution round.
     * @dev Leaf encoding is `keccak256(abi.encode(index, account, amount))`.
     *      The caller must have approved `totalAmount` of `token` to this contract.
     */
    function openRound(
        address token,
        uint256 totalAmount,
        bytes32 merkleRoot,
        uint64 snapshotBlock,
        uint64 opensAt,
        uint64 closesAt,
        string calldata snapshotURI
    ) external onlyRole(DISTRIBUTOR_ROLE) nonReentrant returns (uint256 roundId) {
        if (token == address(0)) revert ZeroAddress();
        if (totalAmount == 0) revert ZeroAmount();
        if (closesAt <= opensAt || closesAt <= block.timestamp) revert InvalidWindow();

        IERC20(token).safeTransferFrom(msg.sender, address(this), totalAmount);

        _rounds.push(
            Round({
                merkleRoot: merkleRoot,
                token: token,
                totalAmount: totalAmount,
                claimedAmount: 0,
                snapshotBlock: snapshotBlock,
                opensAt: opensAt,
                closesAt: closesAt,
                swept: false,
                snapshotURI: snapshotURI
            })
        );
        roundId = _rounds.length - 1;

        emit RoundOpened(
            roundId, token, totalAmount, merkleRoot, snapshotBlock, opensAt, closesAt, snapshotURI
        );
    }

    /// @notice Claim an entitlement. Anyone may submit on a holder's behalf; funds always go to `account`.
    function claim(uint256 roundId, uint256 index, address account, uint256 amount, bytes32[] calldata proof)
        external
        nonReentrant
    {
        if (roundId >= _rounds.length) revert UnknownRound(roundId);
        Round storage r = _rounds[roundId];

        if (block.timestamp < r.opensAt) revert RoundNotOpen(roundId);
        if (block.timestamp > r.closesAt) revert RoundClosed(roundId);
        if (_claimed[roundId].get(index)) revert AlreadyClaimed(roundId, index);

        bytes32 leaf = keccak256(bytes.concat(keccak256(abi.encode(index, account, amount))));
        if (!MerkleProof.verify(proof, r.merkleRoot, leaf)) revert InvalidProof();

        _claimed[roundId].set(index);
        r.claimedAmount += amount;
        totalClaims += 1;

        IERC20(r.token).safeTransfer(account, amount);
        emit Claimed(roundId, index, account, amount);
    }

    /// @notice Return unclaimed funds to the treasury once the window has closed.
    function sweep(uint256 roundId) external onlyRole(DISTRIBUTOR_ROLE) nonReentrant {
        if (roundId >= _rounds.length) revert UnknownRound(roundId);
        Round storage r = _rounds[roundId];
        if (block.timestamp <= r.closesAt) revert RoundStillOpen(roundId);
        if (r.swept) revert AlreadySwept(roundId);

        r.swept = true;
        uint256 remaining = r.totalAmount - r.claimedAmount;
        if (remaining > 0) {
            IERC20(r.token).safeTransfer(treasury, remaining);
        }
        emit RoundSwept(roundId, treasury, remaining);
    }

    function setTreasury(address newTreasury) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newTreasury == address(0)) revert ZeroAddress();
        emit TreasuryUpdated(treasury, newTreasury);
        treasury = newTreasury;
    }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------

    function isClaimed(uint256 roundId, uint256 index) external view returns (bool) {
        return _claimed[roundId].get(index);
    }

    function getRound(uint256 roundId) external view returns (Round memory) {
        if (roundId >= _rounds.length) revert UnknownRound(roundId);
        return _rounds[roundId];
    }

    function roundCount() external view returns (uint256) {
        return _rounds.length;
    }

    /// @notice Recompute a leaf off-chain-compatibly, for SDK and UI use.
    function leafOf(uint256 index, address account, uint256 amount) external pure returns (bytes32) {
        return keccak256(bytes.concat(keccak256(abi.encode(index, account, amount))));
    }
}

contracts/token/RWAToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {IRWAAssetRegistry} from "../interfaces/IRWAAssetRegistry.sol";
import {IComplianceRegistry} from "../interfaces/IComplianceRegistry.sol";

/**
 * @title RWAToken
 * @notice A permissioned ERC-20 representing a 1:1 claim on a custodied
 *         real-world asset registered in {RWAAssetRegistry}.
 *
 * Two invariants are enforced by the contract itself, not by policy:
 *
 *   1. **Backing.** `totalSupply()` can never exceed the reserve figure most
 *      recently attested by the asset's custodian. Minting past the attested
 *      units reverts, so an unbacked token cannot come into existence.
 *
 *   2. **Eligibility.** Every holder — sender and recipient, on every transfer —
 *      must carry a live attestation in {ComplianceRegistry} at or above
 *      `minTier`. Tokens cannot leak to an unverified wallet.
 *
 * Redemption is a burn: the holder destroys tokens and emits a reference that
 * the issuer settles off-chain, at which point the custodian's next attestation
 * reflects the reduced reserve. On-chain supply and off-chain custody therefore
 * converge by construction.
 */
contract RWAToken is ERC20, AccessControl, Pausable {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Asset in {RWAAssetRegistry} this token represents.
    bytes32 public immutable assetId;
    IRWAAssetRegistry public immutable assetRegistry;
    IComplianceRegistry public immutable compliance;

    /// @notice Minimum investor tier required to hold this token (see ComplianceRegistry.Tier).
    uint8 public minTier;

    /// @notice Lifetime issuance and redemption totals, for the reserve report.
    uint256 public totalMinted;
    uint256 public totalRedeemed;

    event Minted(address indexed to, uint256 amount, bytes32 indexed custodyRef, uint256 newSupply);
    event RedemptionRequested(
        address indexed holder, uint256 amount, bytes32 indexed settlementRef, uint256 newSupply
    );
    event MinTierUpdated(uint8 previous, uint8 current);

    error AssetNotMintable(bytes32 assetId);
    error ExceedsAttestedReserves(uint256 attempted, uint256 attested);
    error NotEligible(address account);
    error ZeroAmount();

    constructor(
        string memory name_,
        string memory symbol_,
        bytes32 assetId_,
        address assetRegistry_,
        address compliance_,
        uint8 minTier_,
        address admin
    ) ERC20(name_, symbol_) {
        assetId = assetId_;
        assetRegistry = IRWAAssetRegistry(assetRegistry_);
        compliance = IComplianceRegistry(compliance_);
        minTier = minTier_;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MINTER_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    // ---------------------------------------------------------------------
    // Issuance & redemption
    // ---------------------------------------------------------------------

    /**
     * @notice Issue tokens against custodied reserves.
     * @param custodyRef Reference to the custody instruction authorising this mint
     *                   (keccak256 of the signed subscription record).
     */
    function mint(address to, uint256 amount, bytes32 custodyRef) external onlyRole(MINTER_ROLE) {
        if (amount == 0) revert ZeroAmount();
        if (!assetRegistry.isMintable(assetId)) revert AssetNotMintable(assetId);

        uint256 attested = assetRegistry.attestedUnits(assetId);
        uint256 newSupply = totalSupply() + amount;
        if (newSupply > attested) revert ExceedsAttestedReserves(newSupply, attested);

        _mint(to, amount);
        totalMinted += amount;

        emit Minted(to, amount, custodyRef, newSupply);
    }

    /**
     * @notice Burn tokens to redeem the underlying asset off-chain.
     * @param settlementRef Reference the issuer uses to settle the redemption.
     */
    function requestRedemption(uint256 amount, bytes32 settlementRef) external {
        if (amount == 0) revert ZeroAmount();

        _burn(msg.sender, amount);
        totalRedeemed += amount;

        emit RedemptionRequested(msg.sender, amount, settlementRef, totalSupply());
    }

    /// @notice Forced burn for court orders / sanctions remediation.
    function forceBurn(address from, uint256 amount, bytes32 reasonRef) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _burn(from, amount);
        totalRedeemed += amount;
        emit RedemptionRequested(from, amount, reasonRef, totalSupply());
    }

    // ---------------------------------------------------------------------
    // Transfer eligibility
    // ---------------------------------------------------------------------

    /// @dev OZ v5 routes mint, burn and transfer through `_update`.
    function _update(address from, address to, uint256 value) internal override whenNotPaused {
        // Minting (from == 0): recipient must be eligible.
        // Burning (to == 0): always permitted, so a holder who loses eligibility
        //                    can still exit rather than being trapped.
        // Transfer:          both sides must be eligible.
        if (from != address(0) && to != address(0)) {
            if (!compliance.isVerifiedAtLeast(from, minTier)) revert NotEligible(from);
            if (!compliance.isVerifiedAtLeast(to, minTier)) revert NotEligible(to);
        } else if (from == address(0)) {
            if (!compliance.isVerifiedAtLeast(to, minTier)) revert NotEligible(to);
        }

        super._update(from, to, value);
    }

    // ---------------------------------------------------------------------
    // Admin & views
    // ---------------------------------------------------------------------

    function setMinTier(uint8 newTier) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit MinTierUpdated(minTier, newTier);
        minTier = newTier;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /// @notice Headroom left before the current custody attestation is exhausted.
    function mintableHeadroom() external view returns (uint256) {
        if (!assetRegistry.isMintable(assetId)) return 0;
        uint256 attested = assetRegistry.attestedUnits(assetId);
        uint256 supply = totalSupply();
        return attested > supply ? attested - supply : 0;
    }

    /// @notice Backing ratio in basis points (10000 = fully backed 1:1).
    function backingRatioBps() external view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) return type(uint256).max;
        return (assetRegistry.attestedUnits(assetId) * 10_000) / supply;
    }
}
